import React from 'react';
import styled from 'styled-components';

const ProjectsSection = styled.section`
  width: 100%;
  padding: 4rem 0 2rem 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  background: ${({ theme }) => theme.bg};
`;

const ProjectsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
  gap: 2.5rem;
  width: 90%;
  max-width: 1200px;
  margin: 0 auto;
`;

const ProjectCard = styled.a`
  background: #111;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 16px 0 rgba(0,0,0,0.12);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  text-decoration: none;
  transition: transform 0.18s cubic-bezier(0.4,0,0.2,1), box-shadow 0.18s cubic-bezier(0.4,0,0.2,1);
  will-change: transform;
  ${({ $angle, $offset }) => `
    transform: rotate(${$angle}deg) translateY(${$offset}px);
  `}
  &:hover {
    transform: scale(1.035) rotate(0deg) translateY(-2px);
    box-shadow: 0 6px 32px 0 rgba(0,0,0,0.18);
    z-index: 2;
  }
`;

const ProjectImage = styled.img`
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  background: #222;
  display: block;
`;

const ProjectInfo = styled.div`
    padding: 1rem 1rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    background: #fff;
    text-align: center;
    margin: 1.2rem auto 0 auto;
    position: relative;
    z-index: 2;
`;

const ProjectTitle = styled.div`
  color: #fff;
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 0.2rem;
`;

const ProjectLinkRow = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.7rem;
  margin-top: 0.2rem;
`;

const ProjectDomain = styled.span`
  color: #fff;
  font-size: 1.08rem;
  font-weight: 500;
  opacity: 0.7;
`;

const ArrowIcon = styled.span`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.1rem;
  height: 2.1rem;
  border-radius: 50%;
  background: #fff;
  color: #111;
  font-size: 1.2rem;
  margin-left: 0.2rem;
  transition: background 0.18s, color 0.18s;
  box-shadow: 0 1px 6px 0 rgba(0,0,0,0.08);
`;

const ProjectDesc = styled.p`
  color: #575252ff;
  font-size: 1rem;
  margin-bottom: 0.5rem;
`;

// Placeholder images and info
const projects = [
  {
    title: 'Touravita',
    domain: 'touravita.com',
    url: 'https://touravita.com',
    img: '/images/original-53c3fa50f57e2df119c45f7567f5887e.webp',
  },
  {
    title: 'Hospitalone',
    domain: 'hospitalone.com',
    url: 'https://hospitalone.com',
    img: '/images/image.2.webp',
  },
  {
    title: 'SaaS Dashboard',
    domain: 'saasdashboard.com',
    url: 'https://saasdashboard.com',
    img: '/images/image.3.webp',
  },
  {
    title: 'Creative Agency',
    domain: 'creativeagency.com',
    url: 'https://creativeagency.com',
    img: '/images/image.4.webp',
  },
  {
    title: 'Finance Tool',
    domain: 'financetool.com',
    url: 'https://financetool.com',
    img: '/images/image.5.webp',
  },
  {
    title: 'Outdoor Blog',
    domain: 'outdoorblog.com',
    url: 'https://outdoorblog.com',
    img: '/images/image.6.webp',
  },
];

const Projects = () => (
  <ProjectsSection id="projects">
    <ProjectsGrid>
      {projects.map((project, idx) => {
        // Alternate angles and offsets for a 'breaking' collage look
        const angles = [-4, 3, -2, 5, -3, 2];
        const offsets = [-10, 12, -6, 14, -8, 10];
        const angle = angles[idx % angles.length];
        const offset = offsets[idx % offsets.length];
        return (
          <ProjectCard
            key={idx}
            href={project.url}
            target="_blank"
            rel="noopener noreferrer"
            $angle={angle}
            $offset={offset}
          >
            <ProjectImage src={project.img} alt={project.title} />
            <ProjectInfo>
              <ProjectTitle>{project.title}</ProjectTitle>
              <ProjectDesc>{project.desc}</ProjectDesc>
              <ProjectLinkRow>
                <ProjectDomain>{project.domain}</ProjectDomain>
                <ArrowIcon>
                  <svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M7 11L11 7M11 7H7M11 7V11" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  </svg>
                </ArrowIcon>
              </ProjectLinkRow>
            </ProjectInfo>
          </ProjectCard>
        );
      })}
    </ProjectsGrid>
  </ProjectsSection>
);

export default Projects;
